contributions.text:
{
  "reading": "The question is whether Longshot, Rebel Bowman (3/3 reach, noncreature spells cost {1} less, 2 to each opponent per noncreature spell) earns a slot on jaws-v1 to bring Shark Typhoon and the wheels down a turn. The 99 holds 40 noncreature spells and 21 creatures, the log reads 'slow' in 003, 006 and 007 and records 4 of 9 games as raced, and the pilot wants fewer wheels and more permanents. Longshot is a permanent that speeds the wheels without being one. Pick: Longshot for Reforge the Soul.",
  "log_entries_read": ["003", "004", "006", "007"],
  "axes_engaged": [
    {"axis": "curve", "verdict": "adequate", "measured": {"value": "2"}, "reading": "Longshot (MV 4) replaces a MV 5 card. It joins 11 four-drops in a deck whose modal mana value is 2."},
    {"axis": "interaction", "verdict": "adequate", "measured": {"value": "8"}, "reading": "8 against a target of 8. That is why Collective Defiance, with its 4-to-a-creature mode, is the contested cut and not the pick."},
    {"axis": "sweepers", "verdict": "weakness", "measured": {"value": "0"}, "reading": "The audit counts 0 sweepers, but Kozilek's Return is in the 99. It deals 2 to each creature, so it leaves a 3/3 Longshot alive."}
  ],
  "cut_candidates": [
    {"card": "Reforge the Soul", "why": "Its hard cost is 5 mana, and its miracle {1}{R} needs it to be the first card drawn in a turn, which a wheel-and-cantrip deck cannot arrange. It is one of 9 cards in the wheel group, and the pilot said 'too many wheels, not enough permanent spells'.", "cost_of_cutting": "A wheel: 7 cards and Shabraz counters. The wheel group drops from 9 to 8. Its rare turn-one miracle for {1}{R} is the cheapest wheel in the deck. It appears only as a card discarded from hand in the scenario of stack 001, which was proven on an older list.", "orphans_stack": ["001"], "difficulty": "contested"},
    {"card": "Collective Defiance", "why": "At 3 mana it is the cheapest wheel to cut, but its wheel mode targets one player and refills an opponent's hand.", "cost_of_cutting": "A flexible answer (4 to a creature) plus 3 to a player when the interaction count sits exactly on its target of 8. It is the only wheel with a removal mode.", "orphans_stack": [], "difficulty": "painful"}
  ],
  "add_candidates": [
    {"card": "Longshot, Rebel Bowman", "closes": "A WHEEL drawn — the finisher that grows Shabraz seven cards at a time", "source": "prompt", "why": "With Valeria Richards it brings Shark Typhoon to {3}{U} and every wheel down by 1 or 2. It pings 2 per noncreature spell across 40 noncreature cards. It blocks fliers. With Gratuitous Violence each ping becomes 4, because Longshot is a creature dealing the damage. It survives Kozilek's Return.", "natural_cut": "Reforge the Soul"}
  ],
  "open_questions": [
    {"question": "Teach goldfish cost_reduction to read 'Noncreature spells you cast cost {N} less'. Today it returns None for both Longshot and Valeria Richards.", "settled_by": "goldfish", "why_it_matters": "The reason the pilot asked for this card is invisible to the instrument. A try row would price only the ping."}
  ],
  "gaps": ["No try rows: the reduction is DARK. Study 016's goldfish rows were read on an older list of this branch, and their -42% damage@T10 is not cited.", "No recon on Longshot inclusion in Shabraz/Brallin lists."]
}
